// Embedded high-accuracy photographic specimens from PlantVillage dataset
export const SAMPLE_SPECIMENS = {
  "tomato_blight": "data:image/jpeg;base64,",
  "corn_rust": "data:image/jpeg;base64,",
  "healthy_leaf": "data:image/jpeg;base64,"
};

export function dataURLtoFile(dataurl, filename) {
  const arr = dataurl.split(',');
  const mime = arr[0].match(/:(.*?);/)[1];
  const bstr = atob(arr[1]);
  let n = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new File([u8arr], filename, { type: mime });
}
